const event = $input.first().json;

if (event.type !== 'payment_intent.succeeded') {
  return [{
    json: {
      _skip: true,
      reason: `Unhandled event type: ${event.type}`,
      event_type: event.type
    }
  }];
}

const pi = event.data.object;

const customer_email =
  pi.receipt_email ||
  (pi.charges && pi.charges.data && pi.charges.data[0] &&
   pi.charges.data[0].billing_details &&
   pi.charges.data[0].billing_details.email) ||
  null;

return [{
  json: {
    _skip: false,
    stripe_event_id: event.id,
    event_type: event.type,
    payment_intent_id: pi.id,
    amount_cents: pi.amount,
    currency: pi.currency,
    customer_email: customer_email,
    created: pi.created,
    raw_event: event
  }
}];

const crypto = require('crypto');

// Shared secret between the local Node companion and n8n.
// Must match WORKER_SHARED_SECRET in the companion's environment.
const sharedSecret = 'YOUR_WORKER_SHARED_SECRET';

const input = $input.first().json;
const headers = input.headers || {};
const workerHeader = headers['x-worker-verified'];

if (!workerHeader) {
  throw new Error('Missing X-Worker-Verified header');
}

const expected = Buffer.from(sharedSecret, 'utf8');
const received = Buffer.from(workerHeader, 'utf8');

if (expected.length !== received.length) {
  throw new Error('X-Worker-Verified length mismatch');
}

if (!crypto.timingSafeEqual(expected, received)) {
  throw new Error('X-Worker-Verified did not match');
}

// Return the parsed JSON event. n8n has already parsed the body since the
// companion forwards a valid application/json payload.
return [{ json: input.body }];

