const results = [];
for (const item of $input.all()) {
  const json = item.json;
  const isError = !!json.error;
  const responseText = typeof json === 'string' ? json : (json.body || json);
  results.push({
    json: {
      branch: 'slack',
      status: isError ? 'failed' : 'success',
      error: isError ? (json.error.message || JSON.stringify(json.error)) : null,
      response: responseText
    }
  });
}
return results.length > 0
  ? results
  : [{ json: { branch: 'slack', status: 'failed', error: 'no response', response: null } }];

const results = [];
for (const item of $input.all()) {
  const json = item.json;

  // Resend error shape: { error: { message, name, status, statusCode } }
  // Or wrapped: { error: AxiosError with .message, .status, .statusCode }
  const errObj = json.error;
  const isError = !!errObj ||
                  (json.statusCode && json.statusCode >= 400) ||
                  (json.status && json.status >= 400);

  let status = 'success';
  let errorMessage = null;

  if (isError) {
    status = 'failed';
    if (typeof errObj === 'string') {
      errorMessage = errObj;
    } else if (errObj && errObj.message) {
      errorMessage = errObj.message;
    } else if (errObj && errObj.status) {
      errorMessage = `HTTP ${errObj.status}`;
    } else {
      errorMessage = JSON.stringify(errObj);
    }
  } else if (!json.id) {
    status = 'failed';
    errorMessage = 'no email id in response';
  }

  results.push({
    json: {
      branch: 'resend',
      status: status,
      error: errorMessage,
      response: json
    }
  });
}

return results.length > 0
  ? results
  : [{ json: { branch: 'resend', status: 'failed', error: 'no response', response: null } }];

const results = [];
for (const item of $input.all()) {
  const json = item.json;
  const isError = !!json.error;
  const hasRecord = !!json.id;
  let status = 'success';
  let errorMessage = null;
  if (isError || !hasRecord) {
    status = 'failed';
    errorMessage = typeof json.error === 'string'
      ? json.error
      : (json.error && json.error.message) || 'no record id in response';
  }
  results.push({
    json: { branch: 'airtable', status: status, error: errorMessage, response: json }
  });
}
return results.length > 0
  ? results
  : [{ json: { branch: 'airtable', status: 'failed', error: 'no response', response: null } }];

// Build Audit Row
// Input: three items from Check Slack Result, Check Airtable Result, Check Resend Result
// Output: one item with the fields needed for the Supabase insert

const items = $input.all();

// Index by branch
const byBranch = {};
for (const item of items) {
  const b = item.json.branch;
  if (b) byBranch[b] = item.json;
}

const slack    = byBranch.slack    || { status: 'skipped', error: null };
const airtable = byBranch.airtable || { status: 'skipped', error: null };
const resend   = byBranch.resend   || { status: 'skipped', error: null };

// Compute overall_status
const statuses = [slack.status, airtable.status, resend.status];
const successCount = statuses.filter(s => s === 'success').length;
const failedCount  = statuses.filter(s => s === 'failed').length;

let overall;
if (failedCount === 0 && successCount === 3) {
  overall = 'success';
} else if (successCount === 0) {
  overall = 'failed';
} else {
  overall = 'partial';
}

// Pull the parsed payment event from Parse Payment Event
const event = $('Parse Payment Event').first().json;

return [{
  json: {
    stripe_event_id:   event.stripe_event_id,
    payment_intent_id: event.payment_intent_id,
    amount_cents:      event.amount_cents,
    currency:          event.currency,
    customer_email:    event.customer_email,
    slack_status:      slack.status,
    airtable_status:   airtable.status,
    resend_status:     resend.status,
    slack_error:       slack.error,
    airtable_error:    airtable.error,
    resend_error:      resend.error,
    overall_status:    overall,
    raw_event:         JSON.stringify(event.raw_event)
  }
}];
